package local.money;

import android.app.*;
import android.content.*;
import android.content.pm.*;
import android.net.Uri;
import android.os.Build;
import android.provider.Settings;
import java.io.*;
import java.net.*;
import java.security.MessageDigest;
import java.util.*;
import org.json.*;

final class AppUpdates {
 static final String MANIFEST="https://github.com/rnghx/money-android/releases/latest/download/update.json";
 static final int INSTALL_PERMISSION=412;
 private final Activity activity;
 private volatile boolean busy;
 private JSONObject ready;
 AppUpdates(Activity activity){this.activity=activity;}
 static boolean allowed(URL u){String h=u.getHost().toLowerCase(Locale.ROOT);return "https".equals(u.getProtocol())&&u.getUserInfo()==null&&(u.getPort()==-1||u.getPort()==443)&&(h.equals("github.com")||h.equals("release-assets.githubusercontent.com")||h.equals("objects.githubusercontent.com")||h.equals("github-releases.githubusercontent.com"));}
 static HttpURLConnection connect(String address)throws Exception{URL url=new URL(address);for(int i=0;i<6;i++){if(!allowed(url))throw new IOException("Недопустимый адрес обновления");HttpURLConnection c=(HttpURLConnection)url.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(15000);c.setReadTimeout(30000);c.setRequestProperty("User-Agent","Money-Android-Updater");int code=c.getResponseCode();if(code>=300&&code<400){String location=c.getHeaderField("Location");c.disconnect();if(location==null)throw new IOException("Нет адреса загрузки");url=new URL(url,location);continue;}if(code!=200){c.disconnect();throw new IOException(code==404?"Обновление пока не опубликовано":"Не удалось проверить обновление ("+code+")");}return c;}throw new IOException("Слишком много перенаправлений");}
 static JSONObject validateManifest(JSONObject j)throws Exception{long code=j.getLong("versionCode"),size=j.getLong("size");if(code<1||code>Integer.MAX_VALUE||size<1||size>100*1024*1024||!j.getString("sha256").matches("[a-fA-F0-9]{64}")||!j.getString("versionName").matches("[0-9]+\\.[0-9]+\\.[0-9]+"))throw new IOException("Неверный формат обновления");String url=j.getString("apkUrl");if(!url.startsWith("https://github.com/rnghx/money-android/releases/download/")||!url.endsWith("/app.apk")||!allowed(new URL(url)))throw new IOException("Неверный источник обновления");return j;}
 long installedCode()throws Exception{PackageInfo p=activity.getPackageManager().getPackageInfo(activity.getPackageName(),0);return Build.VERSION.SDK_INT>=28?p.getLongVersionCode():p.versionCode;}
 private void ui(Runnable r){activity.runOnUiThread(()->{if(!activity.isFinishing()&&!activity.isDestroyed())r.run();});}
 private void message(String text){ui(()->new DialogStyle.Builder(activity).setTitle("Обновление приложения").setMessage(text).setPositiveButton("Закрыть",null).show());}
 synchronized void check(){if(busy)return;busy=true;android.widget.Toast.makeText(activity,"Проверка обновления…",android.widget.Toast.LENGTH_SHORT).show();new Thread(()->{try{HttpURLConnection c=connect(MANIFEST);byte[] data;try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){if(out.size()+n>65536)throw new IOException("Слишком большой ответ");out.write(b,0,n);}data=out.toByteArray();}finally{c.disconnect();}JSONObject j=validateManifest(new JSONObject(new String(data,java.nio.charset.StandardCharsets.UTF_8)));if(j.getLong("versionCode")<=installedCode()){message("Установлена последняя версия");return;}ui(()->new DialogStyle.Builder(activity).setTitle("Версия "+j.optString("versionName")).setMessage("Скачать обновление?").setNegativeButton("Позже",null).setPositiveButton("Скачать",(d,w)->download(j)).show());}catch(Exception e){message(error(e));}finally{busy=false;}},"app-update-check").start();}
 private String error(Exception e){return e instanceof IOException?e.getMessage():"Не удалось проверить обновление. Попробуй позднее.";}
 private synchronized void download(JSONObject j){if(busy)return;busy=true;android.widget.Toast.makeText(activity,"Загрузка обновления…",android.widget.Toast.LENGTH_LONG).show();new Thread(()->{File temp=new File(activity.getCacheDir(),"app-update.part"),apk=file(activity);try{HttpURLConnection c=connect(j.getString("apkUrl"));long count=0,expected=j.getLong("size");try(InputStream in=c.getInputStream();OutputStream out=new FileOutputStream(temp)){byte[] b=new byte[16384];int n;while((n=in.read(b))!=-1){count+=n;if(count>expected)throw new IOException("Размер обновления не совпадает");out.write(b,0,n);}}finally{c.disconnect();}if(count!=expected)throw new IOException("Загрузка не завершена");verify(temp,j);if(apk.exists()&&!apk.delete())throw new IOException("Не удалось подготовить обновление");if(!temp.renameTo(apk))throw new IOException("Не удалось сохранить обновление");ready=j;ui(()->new DialogStyle.Builder(activity).setTitle("Обновление загружено").setMessage("Версия "+j.optString("versionName")).setNegativeButton("Позже",null).setPositiveButton("Установить",(d,w)->install()).show());}catch(Exception e){temp.delete();message(error(e));}finally{busy=false;}},"app-update-download").start();}
 static File file(Context c){return new File(c.getCacheDir(),"app-update.apk");}
 private void verify(File file,JSONObject j)throws Exception{MessageDigest hash=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(file)){byte[] b=new byte[16384];int n;while((n=in.read(b))!=-1)hash.update(b,0,n);}StringBuilder hex=new StringBuilder();for(byte b:hash.digest())hex.append(String.format(Locale.ROOT,"%02x",b));if(!hex.toString().equalsIgnoreCase(j.getString("sha256")))throw new IOException("Проверка файла не пройдена");PackageManager pm=activity.getPackageManager();int flags=Build.VERSION.SDK_INT>=28?PackageManager.GET_SIGNING_CERTIFICATES:PackageManager.GET_SIGNATURES;PackageInfo apk=pm.getPackageArchiveInfo(file.getPath(),flags),current=pm.getPackageInfo(activity.getPackageName(),flags);if(apk==null||!activity.getPackageName().equals(apk.packageName))throw new IOException("Файл принадлежит другому приложению");long code=Build.VERSION.SDK_INT>=28?apk.getLongVersionCode():apk.versionCode;if(code!=j.getLong("versionCode")||code<=installedCode())throw new IOException("Версия обновления не совпадает");android.content.pm.Signature[] a=Build.VERSION.SDK_INT>=28?apk.signingInfo.getApkContentsSigners():apk.signatures,b=Build.VERSION.SDK_INT>=28?current.signingInfo.getApkContentsSigners():current.signatures;if(a==null||b==null||a.length==0||!new HashSet<>(Arrays.asList(a)).equals(new HashSet<>(Arrays.asList(b))))throw new IOException("Подпись обновления не совпадает");}
 void permissionResult(){if(ready!=null&&activity.getPackageManager().canRequestPackageInstalls())install();}
 private void install(){if(ready==null)return;if(!activity.getPackageManager().canRequestPackageInstalls()){new DialogStyle.Builder(activity).setTitle("Разрешить обновление").setMessage("Android попросит разрешить установку из этого приложения.").setNegativeButton("Отмена",null).setPositiveButton("Открыть настройки",(d,w)->activity.startActivityForResult(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+activity.getPackageName())),INSTALL_PERMISSION)).show();return;}try{verify(file(activity),ready);Intent intent=new Intent(Intent.ACTION_VIEW).setDataAndType(Uri.parse("content://"+activity.getPackageName()+".updates/app.apk"),"application/vnd.android.package-archive").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);activity.startActivity(intent);}catch(Exception e){message(error(e));}}
}
